const mockClearCart = vi.fn();
const mockItems = [{ id: '1', name: 'Widget', price: 29.99 }];

const renderCheckout = (props = {}, items = mockItems) => {
  return render(
    <CartProvider value={{ items, total: 29.99, clearCart: mockClearCart }}>
      <PaymentProvider value={{ processPayment: mockProcessPayment }}>
        <Checkout {...props} />
      </PaymentProvider>
